USE [BidNile]
GO
-- Data-only script from SSMS Generate Scripts (two passes: all tables except Inventory.Employee, then Inventory.Employee).
-- Warehouse <-> Employee reference each other and some invited members sort before their inviter,
-- so these three foreign keys are paused while loading and re-validated WITH CHECK at the end.
ALTER TABLE [Identity].[Member] NOCHECK CONSTRAINT [FK_Member_Inviter]
ALTER TABLE [Inventory].[Warehouse] NOCHECK CONSTRAINT [FK_Warehouse_Employee]
ALTER TABLE [Inventory].[Item] NOCHECK CONSTRAINT [FK_Item_Employee]
GO
